/**
 * Cliente HTTP PostgREST compatível com @supabase/supabase-js (suporte nativo a custom schema via Accept-Profile / Content-Profile)
 */
class SupabaseRestQueryBuilder {
  constructor(baseUrl, apiKey, table, schema = 'public') {
    this.baseUrl = baseUrl.replace(/\/+$/, '');
    this.apiKey = apiKey;
    this.table = table;
    this.schema = schema;
    this.method = 'GET';
    this.selectParam = '*';
    this.queryParams = new URLSearchParams();
    this.bodyPayload = null;
    this.isSingle = false;
    this.isMaybeSingle = false;
    this.hasSelectAfterWrite = false;
  }

  select(columns = '*') {
    // Normaliza espaços extras em joins como "*, categories ( id, name )" -> "*,categories(id,name)"
    const normalized = String(columns)
      .replace(/\s*\(\s*/g, '(')
      .replace(/\s*\)\s*/g, ')')
      .replace(/\s*,\s*/g, ',')
      .trim();
    this.selectParam = normalized || '*';
    if (this.method !== 'GET') {
      this.hasSelectAfterWrite = true;
    }
    return this;
  }

  insert(payload) {
    this.method = 'POST';
    this.bodyPayload = payload;
    return this;
  }

  update(payload) {
    this.method = 'PATCH';
    this.bodyPayload = payload;
    return this;
  }

  delete() {
    this.method = 'DELETE';
    return this;
  }

  eq(column, value) {
    this.queryParams.append(column, `eq.${value}`);
    return this;
  }

  in(column, values = []) {
    const list = (values || []).join(',');
    this.queryParams.append(column, `in.(${list})`);
    return this;
  }

  order(column, { ascending = true } = {}) {
    this.queryParams.append('order', `${column}.${ascending ? 'asc' : 'desc'}`);
    return this;
  }

  single() {
    this.isSingle = true;
    return this;
  }

  maybeSingle() {
    this.isMaybeSingle = true;
    return this;
  }

  async _execute() {
    try {
      this.queryParams.set('select', this.selectParam);
      const url = `${this.baseUrl}/rest/v1/${encodeURIComponent(this.table)}?${this.queryParams.toString()}`;

      const headers = {
        apikey: this.apiKey,
        Authorization: `Bearer ${this.apiKey}`,
        'Content-Type': 'application/json'
      };

      if (this.method === 'GET' || this.method === 'HEAD') {
        headers['Accept-Profile'] = this.schema;
      } else {
        headers['Content-Profile'] = this.schema;
        headers['Accept-Profile'] = this.schema;
        headers['Prefer'] = 'return=representation';
      }

      const fetchOptions = {
        method: this.method,
        headers
      };

      if (this.bodyPayload !== null && this.method !== 'GET') {
        fetchOptions.body = JSON.stringify(this.bodyPayload);
      }

      const response = await fetch(url, fetchOptions);
      const text = await response.text();
      let parsed = null;
      if (text) {
        try {
          parsed = JSON.parse(text);
        } catch (_) {
          parsed = text;
        }
      }

      if (!response.ok) {
        const errMsg =
          (parsed && (parsed.message || parsed.error || parsed.details || parsed.hint)) ||
          `Erro HTTP ${response.status} ao acessar Supabase`;
        return {
          data: null,
          error: {
            message: errMsg,
            code: parsed && parsed.code ? parsed.code : String(response.status),
            details: parsed
          }
        };
      }

      const rows = Array.isArray(parsed) ? parsed : parsed ? [parsed] : [];

      if (this.isSingle) {
        if (rows.length === 0) {
          return {
            data: null,
            error: { message: 'Registro não encontrado.', code: 'PGRST116' }
          };
        }
        return { data: rows[0], error: null };
      }

      if (this.isMaybeSingle) {
        return { data: rows[0] || null, error: null };
      }

      return { data: rows, error: null };
    } catch (err) {
      return {
        data: null,
        error: { message: err.message || 'Falha de conexão com o Supabase', code: 'FETCH_ERROR' }
      };
    }
  }

  then(resolve, reject) {
    return this._execute().then(resolve, reject);
  }
}

function createClient(supabaseUrl, supabaseKey, options = {}) {
  const schema = (options && options.db && options.db.schema) || 'public';
  return {
    supabaseUrl,
    supabaseKey,
    schemaName: schema,
    schema(customSchema) {
      return createClient(supabaseUrl, supabaseKey, {
        ...options,
        db: { ...(options.db || {}), schema: customSchema }
      });
    },
    from(table) {
      return new SupabaseRestQueryBuilder(supabaseUrl, supabaseKey, table, schema);
    }
  };
}

module.exports = { createClient };
